#pragma once

#include <cstdint>

namespace usage_panel::rlcd {

/**
 * Tables of the 12 x 12 CJK bitmap font.
 *
 * The tables are generated by `tools/rlcd42/gen_cjk_font.py` from the Fusion Pixel
 * 12px font (OFL-1.1); the declarations live apart from the data so the data file
 * stays a generated artefact.
 */
namespace cjk_data {

/** Covered code points in ascending order. */
extern const uint16_t kCjkCodepoints[];
/** One glyph per code point: twelve rows of twelve pixels, two bytes per row. */
extern const uint8_t kCjkGlyphData[];
/** Number of glyphs in the tables. */
extern const int kCjkGlyphCount;

}  // namespace cjk_data

}  // namespace usage_panel::rlcd
